"""Market Lab v0.8: predeclared independent-seed horizons + resumable research.

Closed, synthetic-only market. Two distinct estimands:
  (1) endogenous full-market adaptive-minus-frozen against each arm's Hold;
  (2) deliberately simplified shadow rule execution on an identical, frozen price
      tape, with no market impact, order-book queue or counterfactual liquidity.
The second is NOT equivalent to counterfactual matched-order-book executions.
"""
from __future__ import annotations

import argparse
import csv
from dataclasses import asdict
from hashlib import sha256
from html import escape
