from .interactive import SessionConfig, SyntheticMarket
from .population import STRATEGIES, original_strategy
from .research import _fingerprint
from .research_v07 import METRICS, PRIMARY, interval, parse_seed_range

SCHEMA = 'MARKET_LAB_V08_HOLDOUT_PLAN_1'
RESULT_SCHEMA = 'MARKET_LAB_V08_RESULT_1'
ALGORITHM = 'V08_EXOGENOUS_SHADOW_V1'
FORBIDDEN_SEEDS = frozenset(range(1, 21)) | {42, 43, 44}
OBSERVE_AFTER = 20
DEFAULT_HORIZONS = (320, 640, 1280)
SHADOW_STRATEGIES = STRATEGIES


def _digest(value: dict | list) -> str:
    return sha256(json.dumps(value, sort_keys=True, ensure_ascii=True,
                             separators=(',', ':')).encode('utf-8')).hexdigest()


def _canonical(value: dict) -> bytes:
    return (json.dumps(value, ensure_ascii=False, indent=2, sort_keys=True) + '\n').encode('utf-8')


def parse_horizons(raw: str) -> tuple[int, ...]:
    try:
        result = tuple(int(p.strip()) for p in raw.split(','))
    except ValueError as exc:
        raise ValueError('horizons must be integers, e.g. 320,640,1280') from exc
    if not result or len(result) != len(set(result)) or len(result) > 5 or any(not 20 <= h <= 2000 for h in result):
        raise ValueError('1..5 unique horizons required, each 20..2000')
    return result


def make_plan(seeds: tuple[int, ...] = tuple(range(101, 121)),
              horizons: tuple[int, ...] = DEFAULT_HORIZONS) -> dict:
    if (type(seeds) not in (list, tuple) or not 2 <= len(seeds) <= 100
            or any(type(s) is not int or s < 101 or s > 2**31 or s in FORBIDDEN_SEEDS for s in seeds)
            or len(seeds) != len(set(seeds))):
        raise ValueError('holdout requires 2..100 distinct new seeds >=101; exclude previously used seeds')
    if (type(horizons) not in (tuple, list) or len(horizons) not in range(1, 6)
            or any(type(h) is not int or not 20 <= h <= 2000 for h in horizons)
            or len(horizons) != len(set(horizons))):
        raise ValueError('1..5 distinct horizons, each 20..2000, required')
    body = {
        'schema': SCHEMA, 'source': 'SIMULATED', 'role': 'PREDECLARED_HOLDOUT',
        'seeds': list(seeds), 'horizons': list(horizons),
        'primary_endpoint': PRIMARY, 'shadow_algorithm': ALGORITHM,
        'settings': {
            'events_per_tick': 6, 'waiting_agents': 100, 'evolution_review_ticks': 20,
            'weak_reviews_to_exit': 3, 'max_joins_per_review': 10,
            'maker_fee_bps': 10, 'taker_fee_bps': 20,
            'min_strategy_hold_ticks': 40, 'bankruptcy_threshold_percent': 20,
            'stop_denials': 6, 'maker_caution_ticks': 35,
            'shock_tick': 160, 'shock_enabled': True, 'cancel_percent': 85,
            'sell_qty': 26},
        'cohort_observation_ticks': OBSERVE_AFTER,
        'methodology': (
            'Seed is statistical unit. Compare adaptive/frozen full-market arms after fees, '
            'against each arm own endogenous-price Hold. Shadow rules share one exogenous '
            'price tape generated by the frozen arm; simplified simulated fills cannot '
            'replicate order book or identify real-world causal returns. Original agents, '
            'admitted newcomers and remaining reserves remain in final distributions. '
            'First switch per agent has an observational before/20-tick-after panel; '
            'unobserved follow-ups explicitly censored. No seed 1..20 or 42..44.'),
    }
    for horizon in horizons:
        _config(body, seeds[0], horizon, 'frozen')
        _config(body, seeds[0], horizon, 'adaptive')
    return {**body, 'sha256': _digest(body)}


def verify_plan(plan: dict) -> None:
    if type(plan) is not dict or set(plan) != {
        'schema', 'source', 'role', 'seeds', 'horizons', 'primary_endpoint',
        'shadow_algorithm', 'settings', 'cohort_observation_ticks', 'methodology', 'sha256'
    } or type(plan.get('sha256')) is not str:
        raise ValueError('PLAN_SCHEMA_INVALID')
    body = {k: v for k, v in plan.items() if k != 'sha256'}
    if plan['sha256'] != _digest(body):
        raise ValueError('PLAN_HASH_MISMATCH')
    if plan != make_plan(tuple(plan['seeds']), tuple(plan['horizons'])):
        raise ValueError('PLAN_NOT_CANONICAL')


def _config(plan: dict, seed: int, horizon: int, arm: str) -> SessionConfig:
    if arm not in ('frozen', 'adaptive'):
        raise ValueError('invalid arm')
    kwargs = dict(plan['settings'])
    kwargs['shock_tick'] = min(horizon, kwargs['shock_tick'])
    return SessionConfig(seed=seed, ticks=horizon, evolution_enabled=True,
                         adaptation_enabled=(arm == 'adaptive'), **kwargs)


def _agent_score(m: SyntheticMarket, agent: str, price: int) -> float:
    c0, q0 = m.population.initial_wallets[agent]
    w = m.economy.wallets[agent]
    return round((w.cash_ticks + w.coin_qty * price - c0 - q0 * price) / 10, 5)


def _cohorts(m: SyntheticMarket) -> list[dict]:
    """Every initially funded wallet stays in exactly one final cohort."""
    p = m.population
    price = m.book.last_trade_ticks
    grouped: dict[str, list[float]] = {}
    for aid in sorted(p.initial_wallets):
        initial = ('original_' + original_strategy(aid)) if aid in p.initial_active_ids else (
            'admitted_reserve' if aid in p.active or aid in p.retired else 'remaining_reserve')
        grouped.setdefault(initial, []).append(_agent_score(m, aid, price))
    return [{'cohort': name, 'count': len(vals), 'mean_vs_hold_vcu': round(mean(vals), 5),
             'median_vs_hold_vcu': round(median(vals), 5),
             'ahead_percent': round(100 * sum(x > 0 for x in vals) / len(vals), 5)}
            for name, vals in sorted(grouped.items())]


def run_arm(plan: dict, seed: int, horizon: int, arm: str) -> dict:
    m = SyntheticMarket(_config(plan, seed, horizon, arm))
    initial = _fingerprint(m)
    pre_review = None
    prior_changes: dict[str, int] = {}
    switches: dict[str, dict] = {}
    observe_after = plan['cohort_observation_ticks']
    for _ in range(horizon):
        m.step(capture_state=False)
        t = m.tick
        if t == min(horizon, m.config.evolution_review_ticks - 1):
            pre_review = _fingerprint(m)
        # The before state is taken immediately after the switching review;
        # trades have already settled, and the strategy has JUST changed.
        if arm == 'adaptive' and t % m.config.evolution_review_ticks == 0:
            for aid, member in m.population.active.items():
                now = member.strategy_changes
                if now > prior_changes.get(aid, 0) and aid not in switches:
                    switches[aid] = {
                        'agent': aid,
                        'cohort': ('original_' + original_strategy(aid))
                                  if aid in m.population.initial_active_ids else 'admitted_reserve',
                        'first_switch_tick': t, 'from_original_rule': original_strategy(aid),
                        'to_rule': member.strategy,
                        'before_vs_hold_vcu': _agent_score(m, aid, m.book.last_trade_ticks),
                        'followup_tick': t + observe_after,
                        'after_vs_hold_vcu': None,
                        'change_vs_hold_vcu': None, 'censored': True,
                        'retired_at_followup': None,
                    }
                prior_changes[aid] = now
        if switches:
            for record in switches.values():
                if record['followup_tick'] == t:
                    aid = record['agent']
                    after = _agent_score(m, aid, m.book.last_trade_ticks)
                    record['after_vs_hold_vcu'] = after
                    record['change_vs_hold_vcu'] = round(after - record['before_vs_hold_vcu'], 5)
                    record['censored'] = False
                    record['retired_at_followup'] = aid in m.population.retired
    if not (m.economy.check(m.book) and m.population.check() and m.book.check_conservation()):
        raise AssertionError('CONSERVATION_FAILED')
    snap = m.state()
    if not (snap['economy_conservation_pass'] and snap['conservation_pass']
            and snap['economy']['pnl_identity_pass'] and snap['population']['conservation_pass']):
        raise AssertionError('ENDPOINT_CONSERVATION_FAILED')
    rel = snap['population']['relative_to_hold']
    result = {'relative_vs_hold_vcu': rel['total_relative_vcu'],
              'mean_relative_per_agent_vcu': rel['mean_relative_vcu'],
              'median_relative_vcu': rel['median_relative_vcu'],
              'p10_relative_vcu': rel['p10_relative_vcu'],
              'p90_relative_vcu': rel['p90_relative_vcu'],
              'ahead_percent': rel['ahead_percent'],
              'fees_vcu': snap['economy']['fees_total_vcu'],
              'trades': snap['total_trades'], 'volume': snap['volume'],
              'last_price_vcu': snap['market']['last_price'],
              'strategy_switches': snap['population']['strategy_switches'],
              'retired_agents': snap['population']['retired'],
              'joins': snap['population']['admitted'],
              'active_agents': snap['population']['active']}
    return {'seed': seed, 'horizon': horizon, 'arm': arm,
            'metrics': result, 'initial_fingerprint': initial,
            'pre_review_fingerprint': pre_review,
            'price_tape_ticks': m.price_history if arm == 'frozen' else None,
            'cohorts': _cohorts(m), 'first_switches': list(switches.values()),
            'all_wallets': rel['all_agents'], 'conservation': True}


def shadow_rules(price_tape: list[int], seed: int, *, maker_fee_bps: int = 10,
                 taker_fee_bps: int = 20) -> list[dict]:
    """Identical exogenous price tape and decision opportunities for rule proxies.

    Taker proxy fills at reference price +/- one tick; maker proxy submits a
    quote 2 ticks away and fills at the next tick only on crossed reference.
    No orderbook/queue, no market impact; these are NOT v0.7 market executions.
    """
    if len(price_tape) < 21 or any(type(px) is not int or px <= 0 for px in price_tape):
        raise ValueError('invalid synthetic price tape')
    start_cash = 10_000  # 1000 VCU, integer 0.1 VCU ticks
    start_coins = 10
    results = []
    tape_hash = _digest(price_tape)
    for strategy in SHADOW_STRATEGIES:
        cash = start_cash
        coins = start_coins
        fills = 0
        fees = 0
        opportunities = 0
        for t in range(8, len(price_tape) - 1, 5):
            px = price_tape[t]
            trend = px - price_tape[t - 8]
            rng = random.Random((seed * 7_919_971 + t * 10_007) & 0xffff_ffff_ffff_ffff)
            random_buy = bool(rng.getrandbits(1))
            if strategy in ('NOISE', 'MAKER'):
                side_buy = random_buy
            elif strategy == 'TREND':
                side_buy = trend > 0 if trend else random_buy
            else:
                side_buy = trend < 0 if trend else random_buy
            opportunities += 1
            if strategy == 'MAKER':
                quote = px - 2 if side_buy else px + 2
                crossed = (price_tape[t + 1] <= quote if side_buy else price_tape[t + 1] >= quote)
                if not crossed or quote <= 0:
                    continue
                execution_price = quote
                basis_points = maker_fee_bps
            else:
                execution_price = px + 1 if side_buy else max(1, px - 1)
                basis_points = taker_fee_bps
            fee_ticks = (execution_price * basis_points + 9_999) // 10_000
            if side_buy and cash >= execution_price + fee_ticks:
                cash -= execution_price + fee_ticks
                coins += 1
            elif not side_buy and coins >= 1:
                cash += execution_price - fee_ticks
                coins -= 1
            else:
                continue
            fees += fee_ticks
            fills += 1
        last = price_tape[-1]
        delta = cash + coins * last - start_cash - start_coins * last
        results.append({'strategy': strategy, 'tape_sha256': tape_hash,
                        'vs_hold_vcu': round(delta / 10, 5),
                        'fills': fills, 'opportunities': opportunities,
                        'fees_vcu': round(fees / 10, 5)})
    return results


def _atomic_bytes(path: Path, data: bytes) -> None:
    """Write checkpoint fully, fsync, and atomically rename in same directory."""
    path.parent.mkdir(parents=True, exist_ok=True)
    name = None
    try:
        with tempfile.NamedTemporaryFile(dir=path.parent, prefix='.pending-', delete=False) as f:
            name = f.name
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        os.replace(name, path)
    finally:
        if name and os.path.exists(name):
            os.unlink(name)


def _checkpoint_name(seed: int, horizon: int, arm: str) -> str:
    return f'seed-{seed}-ticks-{horizon}-{arm}.json'


def _seal(payload: dict) -> dict:
    return {**payload, 'content_sha256': _digest(payload)}


def _open_checkpoint(path: Path, plan: dict, seed: int, horizon: int, arm: str) -> dict:
    chk = json.loads(path.read_bytes())
    if type(chk) is not dict or set(chk) != {'plan_sha256', 'seed', 'horizon', 'arm', 'data', 'content_sha256'}:
        raise ValueError(f'CHECKPOINT_SCHEMA_MISMATCH {path}')
    if (chk['content_sha256'] != _digest({k: v for k,v in chk.items() if k != 'content_sha256'})
            or (chk['plan_sha256'],chk['seed'],chk['horizon'],chk['arm']) !=
               (plan['sha256'], seed, horizon, arm)):
        raise ValueError(f'CHECKPOINT_INTEGRITY_FAILED {path}')
    result = chk['data']
    if not isinstance(result, dict) or result.get('conservation') is not True or result.get('all_wallets') != 1000:
        raise ValueError(f'CHECKPOINT_CONSERVATION_OR_COUNT_FAILED {path}')
    if result.get('seed') != seed or result.get('horizon') != horizon or result.get('arm') != arm:
        raise ValueError(f'CHECKPOINT_DATA_MISMATCH {path}')
    return result


def _csv_bytes(rows: list[dict], cols: list[str]) -> bytes:
    from io import StringIO
    f = StringIO(newline='')
    writer = csv.DictWriter(f, fieldnames=cols, extrasaction='raise', lineterminator='\n')
    writer.writeheader()
    writer.writerows(rows)
    return ('\ufeff' + f.getvalue()).encode('utf-8')


def _collect(plan: dict, checkpoints: list[dict]) -> dict:
    by_key = {(c['seed'],c['horizon'],c['arm']):c for c in checkpoints}
    runs, pairs, cohorts, changes, shadow = [], [], [], [], []
    for horizon in plan['horizons']:
        for seed in plan['seeds']:
            frozen = by_key[(seed,horizon,'frozen')]
            adaptive = by_key[(seed,horizon,'adaptive')]
            if ((frozen['initial_fingerprint'],frozen['pre_review_fingerprint']) !=
                    (adaptive['initial_fingerprint'],adaptive['pre_review_fingerprint'])):
                raise AssertionError(f'PAIR_FINGERPRINT_MISMATCH seed={seed} horizon={horizon}')
            if len(frozen['price_tape_ticks']) != horizon + 1:
                raise AssertionError('PRICE_TAPE_LENGTH_MISMATCH')
            for arm_data in (frozen,adaptive):
                runs.append({'seed': seed, 'horizon': horizon, 'arm': arm_data['arm'], **arm_data['metrics']})
                cohorts.extend({'seed': seed, 'horizon': horizon, 'arm': arm_data['arm'], **v}
                               for v in arm_data['cohorts'])
                changes.extend({'seed':seed, 'horizon':horizon, **v}
                               for v in arm_data['first_switches'])
            pairs.append({'seed': seed, 'horizon': horizon,
                          **{'delta_' + k: adaptive['metrics'][k] - frozen['metrics'][k]
                             for k in METRICS}})
            shadow.extend({'seed':seed, 'horizon':horizon, **v} for v in
                          shadow_rules(frozen['price_tape_ticks'],seed,
                                       maker_fee_bps=plan['settings']['maker_fee_bps'],
                                       taker_fee_bps=plan['settings']['taker_fee_bps']))
    statistics = []
    for horizon in plan['horizons']:
        for metric in METRICS:
            for arm in ('frozen','adaptive','delta'):
                vals = ([r['delta_'+metric] for r in pairs if r['horizon']==horizon]
                        if arm=='delta' else
                        [r[metric] for r in runs if r['horizon']==horizon and r['arm']==arm])
                statistics.append({'horizon':horizon,'metric':metric,'group':arm,**interval(vals)})
    shadow_stats = []
    for horizon in plan['horizons']:
        for strategy in SHADOW_STRATEGIES:
            vals = [r['vs_hold_vcu'] for r in shadow if r['horizon']==horizon and r['strategy']==strategy]
            shadow_stats.append({'horizon': horizon, 'strategy': strategy, **interval(vals)})
    return {'schema':RESULT_SCHEMA, 'source':'SIMULATED', 'plan_sha256':plan['sha256'],
            'runs':runs, 'pairs':pairs, 'cohorts':cohorts, 'first_switches':changes,
            'shadow':shadow, 'statistics':statistics, 'shadow_statistics':shadow_stats,
            'integrity': {'conservation_all_runs': True, 'paired_initial_match':True,
                          'paired_pre_review_match':True, 'all_1000_wallets_included':True},
            'limitations': ('Endogenous paired markets can have different execution prices; '
                            'shadow execution uses frozen tape, simplified trade signals and '
                            'hypothetical fills, not order-book executions. First-switch '
                            'before/after changes are observational, censored after horizon; '
                            'repeated seeds across horizons are NOT independent replications. '
                            '95% intervals are seed-based, not agent-based; multiple secondary '
                            'comparisons are exploratory. No real prices or trading.')}


