    for h in plan['horizons']:
        st = next(s for s in result['statistics'] if s['horizon']==h and s['group']=='delta'
                  and s['metric']==PRIMARY)
        head.append('<tr>'+''.join(f'<td>{escape(str(x))}</td>' for x in
                    (h, st['mean'],st['ci95_low'],st['ci95_high'],st['positive'],st['negative']))+'</tr>')
    shadow_rows=[]
    for st in result['shadow_statistics']:
        shadow_rows.append('<tr>'+''.join(f'<td>{escape(str(x))}</td>' for x in
                           (st['horizon'],st['strategy'],st['mean'],st['ci95_low'],st['ci95_high']))+'</tr>')
    obs = [x for x in result['first_switches'] if not x['censored']]
    cohort_rows=[]
    for h in plan['horizons']:
        for arm in ('frozen','adaptive'):
            for c in (x for x in result['cohorts'] if x['horizon']==h and x['arm']==arm):
                cohort_rows.append('<tr>'+''.join(f'<td>{escape(str(x))}</td>' for x in
                    (h,arm,c['cohort'],c['count'],c['mean_vs_hold_vcu'],c['ahead_percent']))+'</tr>')
    first_rows=[]
    for h in plan['horizons']:
        for group in ('original','admitted_reserve'):
            relevant=[x for x in result['first_switches'] if x['horizon']==h and
                      (x['cohort'].startswith('original_') if group=='original' else
                       x['cohort']=='admitted_reserve')]
            observed=[x['change_vs_hold_vcu'] for x in relevant if not x['censored']]
            first_rows.append('<tr>'+''.join(f'<td>{escape(str(x))}</td>' for x in
                (h,group,len(relevant),len(observed),len(relevant)-len(observed),
                 round(mean(observed),4) if observed else 'n/a'))+'</tr>')
